def find_blocks(g,val):
    h,w=len(g),len(g[0]); seen=set(); res=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]==val and (r,c) not in seen:
                stack=[(r,c)]; comp=[]
                while stack:
                    a,b=stack.pop()
                    if (a,b) in seen or not(0<=a<h and 0<=b<w) or g[a][b]!=val: continue
                    seen.add((a,b)); comp.append((a,b))
                    stack+= [(a+1,b),(a-1,b),(a,b+1),(a,b-1)]
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                res.append((min(rs),max(rs),min(cs),max(cs),len(comp)))
    return res
