from collections import deque
def f(a):
    h,w=len(a),len(a[0])
    out=[row[:] for row in a]
    ones=[(r,c) for r in range(h) for c in range(w) if a[r][c]==1]
    # draw full lines through aligned one-pairs
    seen_lines=set()
    for (r1_,c1_),(r2_,c2_) in combinations([p for p in ones],2):
        if r1_==r2_:
            key=('row',r1_,min(c1_,c2_),max(c1_,c2_))
        elif c1_==c2_:
            key=('col',c1_,min(r1_,r2_),max(r1_,r2_))
        else: continue
        seen_lines.add(key)
    for kind,pos,minv,maxv in seen_lines:
        rng=range(minv,maxv+1) if kind=='col' else range(minv,maxv+1)
        for idx in rng:
            rr,cc=(pos,idx) if kind=='col' else (idx,pos)
            out[rr][cc]=1
    # flood 2s adjacent to drawn-1 cells
    draw=[[1 if out[r][c]==1 and a[r][c]!=1 else 0 for c in range(w)] for r in range(h)]
    q=deque()
    for r in range(h):
        for c in range(w):
            if a[r][c]==2 and draw[r][c]: q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            rr,cc=r+dr,c+dc
            if 0<=rr<h and 0<=cc<w and a[rr][cc]==2 and not out[rr][cc]:
                out[rr][cc]=1; q.append((rr,cc))
    return out
