    pts=[(r,c) for r in range(H) for c in range(W) if inp[r][c]==1]
    # pair markers by row or column: markers whose row/col segment contains 2-cells are "inside"; those with none are "anchors"
    def pairs(pts):
        seg=set(); used=set(pts)
        while len(used)>=2:
            found=False
            for p,q in itertools.combinations(sorted(used),2):
                if p[0]==q[0]:
                    seg|={(p[0],c) for c in range(min(p[1],q[1]),max(p[1],q[1])+1)}
                    found=True; break
                if p[1]==q[1]:
                    seg|={(r,p[1]) for r in range(min(p[0],q[0]),max(p[0],q[0])+1)}
                    found=True; break
            if not found: break
            a=min(sorted(used))
            b=max(sorted(used))
            used.discard(a); used.discard(b)
        return seg
    seg=pairs(pts)
    for r,c in seg:
        if out[r][c]!=1: out[r][c]=1
    return out
